cases.bad:
.subtitle-block {
  cursor: grab;
  pointer-events: auto;
  /* thiếu touch-action — browser scroll trang YouTube khi chạm+kéo */
}

cases.good:
.subtitle-block {
  cursor: grab;
  pointer-events: auto;
  touch-action: none; /* browser không scroll/zoom ở đây, JS nhận trọn gesture */
}

cases.bad:
.cell-token-fab {
  position: fixed !important;
  cursor: pointer !important;
  /* thiếu touch-action — pointercancel bắn khi browser bắt đầu scroll */
}

cases.good:
.cell-token-fab {
  position: fixed !important;
  cursor: pointer !important;
  touch-action: none !important; /* !important vì .btn--primary có thể override */
}
